local BackpackBatchSellPanel = Class('BackpackBatchSellPanel')

function BackpackBatchSellPanel:__init()
    self.goodsVo = nil
    self.data = nil
    self.container = nil
    self.goodsNode = nil
    self.empty = nil
    self.cb = nil
    self.imgBg = nil
end

function BackpackBatchSellPanel:__delete()
    self.goodsVo = nil
    self.goodsNode = nil
    self.data = nil
    self.imgBg = nil
    self.cb = nil
end

function BackpackBatchSellPanel:Awake()
    self.container = self.BuyNumGroup.transform.parent
    self.goodsNode = self.container:Find("GoodsDescNode")
    self.empty = self.container.parent:Find("Empty")
    self.imgBg = self.controller.transform:Find("AnimRoot/ImgBg")
    SetButtonAction(self.FontStyleButton, function()
        ---出售按钮的逻辑
        if self.cb then
            self.cb(1)
        end
    end)
end

function BackpackBatchSellPanel:SetEmpty(isShowEmptyNode, isShowContainer, isShowBg)
    KTool.SetActive(self.container.gameObject, isShowContainer)
    KTool.SetActive(self.empty.gameObject, isShowEmptyNode)
    CfUtils.SetActive(self.imgBg, isShowBg)
end

function BackpackBatchSellPanel:SetGoodName()
    ---@type GoodsVo
    local goodsVo = self.goodsVo
    if goodsVo then
        CfUtils.FillImage(self.GoodQuality, GoodsUtils.GetFishBgByQualityType(goodsVo.quality))
        CfUtils.FillText(self.TextName, goodsVo.name)
        CfUtils.FillImage(self.ImgIcon, goodsVo.photoPath)
        CfUtils.FillText(self.TextDesc1, goodsVo.description)
        CfUtils.FillText(self.TextDesc2, goodsVo.desc)
    end
end

function BackpackBatchSellPanel:SetNumberEditAction(cb)
    self.cb = cb
end

function BackpackBatchSellPanel:SetSellTextInfo()
    ---设置卖出信息
    ---@type GoodsVo
    local goodsVo = self.goodsVo
    if goodsVo then
        --local photoPath = GoodsConfMgr:GetInstance():GetPhotoPathById(goodsVo.sellitem)
        local photoPath = GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.GoldId)
        CfUtils.FillImage(self.priceIcon, photoPath)
    end
    local backpack = UIModule.CurrentScreen:GetDialog(Constants.UITypeIds.Backpack)
    if backpack and backpack.Env then
        ---@type Backpack
        local env = backpack.Env
        if env then
            local num = 0
            ---@type GoodsConfMgr
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            for k, v in pairs(env.consume) do
                local vo = goodsConfMgr:GetGoodsVoById(v.data.goodsId)
                if vo then
                    num = num + math.floor(checkNumber(vo.sellmoney) * checkNumber(v.data.preNo))
                end
            end
            CfUtils.FillText(self.priceText, num)
        end
    end
end

---FreshEquipInfo
---装备信息显示
function BackpackBatchSellPanel:FreshEquipInfo()

    ---@type EquipmentComponent
    local equipmentComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
    local equipDoJo = equipmentComponent:GetEquipById(self.data.vo.id) -- 装备分支
    ---@type EquipVo
    local equipVo = CardConfMgr:GetInstance():GetEquipVoById(equipDoJo.equipmentId)
    if isNull(equipVo) then
        return
    end
    KTool.SetActive(self.ImgStrengthen.gameObject, checkNumber(equipDoJo.level) > 0)
    if checkNumber(equipDoJo.level) > 0 then
        CfUtils.SetUISwitchImage(self.ImgStrengthen, checkNumber(equipDoJo.level))
    end

    --CfUtils.SetUISwitchImage(self.ImgStrengthen.gameObject, math.min(checkNumber(equipDoJo.level) + 1, 6))
    CfUtils.FillImage(self.equipTypeIcon.gameObject, EquipUtils.GetEquipmentSetIcon(equipVo.equipId))
    local count = self.StarGroup.transform.childCount
    KTool.SetActive(self.ImgStar.gameObject, false)
    local children = {}
    for i = 1, count do
        local child = self.StarGroup.transform:GetChild(i - 1)
        if child and child.name ~= "ImgStar" then
            table.insert(children, child)
        end
    end
    for i, v in pairs(children) do
        KTool.SafeDelete(v.gameObject, true)
    end
    children = nil
    --print('---->>>', equipDoJo.star)
    ---构建星级
    for i = 1, checkNumber(equipDoJo.star) do
        local go = KTool.Instantiate(self.StarGroup.gameObject, self.ImgStar.gameObject, false)
        KTool.SetActive(go, true)
        go.name = 'Start_' .. i
    end
    KTool.SetActive(self.MainAttribute.gameObject, true)
    self:SetEquipAttrNodeInfo(self.MainAttribute.gameObject, equipDoJo.mainAttrId, equipDoJo.mainAttrNum) -- 设置主属性
    local transBGImg = self.MainAttribute.transform:Find("Imgbg")
    if not IsNull(transBGImg) then
        local bgImage = KTool.GetComponent(transBGImg.gameObject, typeof(Image))
        if not IsNull(bgImage) then
            bgImage.enabled = true
        end
    end
    self:SetEquipSubAttrList(equipDoJo) -- 设置副属性
end
--SetEquipAttrNodeInfo
---设置装备属性信息
---@param go UnityEngine.GameObject 节点 GO
---@param pAttrId number 主属性 ID
---@param attrValue number 主属性数值
function BackpackBatchSellPanel:SetEquipAttrNodeInfo(go, pAttrId, attrValue, title, attrQuality)
    local node_AttrLocked = go.transform:Find(AttrLockedNodePath)
    local node_AttrUnlocked = go.transform:Find(AttrNodePathTitle)
    if not IsNull(node_AttrUnlocked) then
        KTool.SetActive(node_AttrUnlocked.gameObject, true)
    end
    if not IsNull(node_AttrLocked) then
        KTool.SetActive(node_AttrLocked.gameObject, false)
    end
    local attrAdditionData = CardConfMgr:GetInstance():GetBasicAttrAdditionById(pAttrId)
    local attrId = attrAdditionData.attrId
    local attrData = CardConfMgr:GetInstance():GetBasicAttr(attrId)
    local txt_AttrName = go.transform:Find(title and string.format("%s%s%s", AttrNodePathTitle, "/", AttrNameNodePath) or AttrNameNodePath):GetComponent(typeof(Text))
    local txt_AttrValue = go.transform:Find(title and string.format("%s%s%s", AttrNodePathTitle, "/", AttrValueNodePath) or AttrValueNodePath):GetComponent(typeof(TextMeshProUGUI))
    KTool.SetActive(txt_AttrName.gameObject, true)
    KTool.SetActive(txt_AttrValue.gameObject, true)
    --local iconAttr = go.transform:Find(title and string.format("%s%s%s", AttrNodePathTitle, "/", AttrRawImg) or AttrRawImg):GetComponent(typeof(RawImageAlterable))
    --if not IsNull(iconAttr) then
    --    KTool.SetActive(iconAttr.gameObject, (not IsNull(attrData.icon)) and attrData.icon ~= "")
    --    iconAttr:LoadSprite(attrData.icon)
    --end
    txt_AttrName.text = attrData.name
    if attrQuality then
        txt_AttrValue.text = tostring(attrValue)
    else
        local attrIsConversion = attrAdditionData.isConversion
        txt_AttrValue.text = tostring(attribute_format(attrIsConversion, attrValue))
    end
end

---SetEquipSubAttrList
---设置装备副属性列表
---@param equipDJ EquipDojo
function BackpackBatchSellPanel:SetEquipSubAttrList(equipDJ)
    local star = checkNumber(equipDJ.star)
    local count = self.SecondaryAttribute.transform.childCount
    local children = {}
    for i = 1, count do
        local child = self.SecondaryAttribute.transform:GetChild(i - 1)
        if child and child.name ~= "AttributeNode" then
            table.insert(children, child)
        end
    end
    for i, v in pairs(children) do
        KTool.SafeDelete(v.gameObject, true)
    end
    children = nil
    KTool.SetActive(self.AttributeNode.gameObject, false)

    local subAttrMaxCount = EquipUtils.GetEquipmentSubAttrMaxCountByDojo(equipDJ)
    for i = 1, CardProgressionConstants.EquipmentSubAttrLimit do
        --- 需要实例化游戏物体
        local go = KTool.Instantiate(self.SecondaryAttribute.gameObject, self.AttributeNode.gameObject, false)
        local isShow = i <= subAttrMaxCount
        KTool.SetActive(go, isShow)
        if isShow then
            go.name = "Attribute" .. tostring(i)
            local attrAdditionId = checkNumber(equipDJ[string.format("attr%sId", i)])
            local isOwnAttr = star >= i
            if isOwnAttr then
                --- 已解锁的属性
                -- <name:属性名称, attrNum:显示属性, attrQuality:属性品质>
                local t = EquipUtils.GetSubAttrByIndex(equipDJ, i)
                self:SetEquipAttrNodeInfo(go, attrAdditionId, t.attrNum, AttrNodePathTitle, t.attrQuality)
            else
                --- 未解锁的属性
                self:SetEquipAttrNodeLocked(go, i)
            end
            local bgImage = KTool.GetComponent(go, typeof(Image))
            if not IsNull(bgImage) then
                bgImage.enabled = i % 2 == 0
            end
        end
    end
end

---SetEquipAttrNodeLocked
---设置锁定的 AttrNode
---@param go UnityEngine.GameObject
---@param star string
function BackpackBatchSellPanel:SetEquipAttrNodeLocked(go, star)
    local node_AttrLocked = go.transform:Find(AttrLockedNodePath)
    local node_AttrUnlocked = go.transform:Find(AttrNodePathTitle)
    KTool.SetActive(node_AttrUnlocked.gameObject, false)
    KTool.SetActive(node_AttrLocked.gameObject, true)
    local txt_UnLockLV = node_AttrLocked:Find(TxtSubAttrUnLockPath):GetComponent(typeof(Text))
    if not IsNull(txt_UnLockLV) then
        txt_UnLockLV.text = localize("_num_星解锁", { _num_ = checkString(star) })
    end
end

function BackpackBatchSellPanel:FreshUI(data)
    self.data = data
    KTool.SetActive(self.goodsNode, true)
    KTool.SetActive(self.BuyNumGroup.gameObject, checkNumber(data.num) > 1)
    if data.num > 1 then
        ---@type SellActionInput
        local env = CfUtils.GetLuaScr(self.BuyNumGroup.gameObject, SellActionInputPath)
        env:FreshUI(checkNumber(data.num), data.num)
        env:SetInputActionEvent(function(no)
            data.preNo = no
            if self.cb then
                self.cb(0)
            end
            self:SetSellTextInfo()
        end)
    end
    ---@type GoodsVo
    local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(data.goodsId)
    self.goodsVo = goodsVo
    local goodType = checkNumber(goodsVo.type)
    KTool.SetActive(self.Equip.gameObject, goodType == Constants.IDType.Equipment)
    KTool.SetActive(self.EquipDisplay.gameObject, goodType == Constants.IDType.Equipment)
    self:SetSellTextInfo()
    self:SetGoodName()
    if checkNumber(goodsVo.type) == Constants.IDType.Equipment then
        local otherGoods = self.TextName.transform.parent:Find("OtherGoods")
        if otherGoods then
            KTool.SetActive(otherGoods.gameObject, false)
        end
        ---装备情况下
        self:FreshEquipInfo()
    end
end

function BackpackBatchSellPanel:FreshSellStateUI()
    KTool.SetActive(self.BuyNumGroup.gameObject, false)
    KTool.SetActive(self.goodsNode, false)
    KTool.SetActive(self.Equip.gameObject, false)
    KTool.SetActive(self.EquipDisplay.gameObject, false)
    self:SetSellTextInfo()
end

function BackpackBatchSellPanel:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return BackpackBatchSellPanel